def _warn_if_value_exceeds_max_size(value: JsonValue, key: str) -> None:
    """
    Emit a warning when the serialized ``value`` exceeds ``[state_store] max_value_storage_bytes``.

    This mirrors the server-side limit so task authors get early feedback. It only warns —
    the caller still sends the value; the API is the authoritative enforcement point. A
    configured limit of ``0`` disables the check.
    """
    import json

    max_bytes = conf.getint("state_store", "max_value_storage_bytes", fallback=0)
    if max_bytes <= 0:
        return
    size = len(json.dumps(value).encode("utf-8"))
    if size > max_bytes:
        log.warning(
            "State store value for key %r is %d bytes, which exceeds the configured "
            "[state_store] max_value_storage_bytes limit of %d bytes. The API may reject it.",
            key,
            size,
            max_bytes,
        )


